import unittest

import numpy as np

from grayrecon.data import box_kernel, random_mask
from grayrecon.generator import Generator
from grayrecon.operators import MaskedBlur
from grayrecon.solver import SolveError, Status, solve, solve_inverse


def solvable_problem(seed=0, shape=(8, 8), latent_dim=3, hidden_dim=10,
                     missing=0.3):
    """Problem whose observation is exactly generated by the network."""
    rng = np.random.default_rng(seed)
    n = shape[0] * shape[1]
    w1 = rng.standard_normal((latent_dim, hidden_dim)) / np.sqrt(latent_dim)
    b1 = rng.standard_normal(hidden_dim) * 0.1
    w2 = rng.standard_normal((hidden_dim, n)) / np.sqrt(hidden_dim)
    b2 = rng.standard_normal(n) * 0.05
    gen = Generator(w1, b1, w2, b2, shape)
    z_star = rng.standard_normal(latent_dim) * 0.5
    x_star, _, _, _ = gen.forward(z_star)
    mask = random_mask(shape, missing, seed=seed + 100).astype(float)
    op = MaskedBlur(shape, box_kernel(3), mask)
    y = op(x_star)
    return op, y, gen, x_star


class TestPixelGradientStep(unittest.TestCase):
    """Finite-difference check of the pixel-space data-fit gradient A*(Ax-y)."""

    def test_adjoint_gradient_matches_finite_difference(self):
        rng = np.random.default_rng(42)
        shape = (7, 7)
        mask = (rng.random(shape) > 0.4).astype(float)
        op = MaskedBlur(shape, box_kernel(3), mask)
        x = rng.standard_normal(shape)
        y = rng.standard_normal(shape)

        def residual_half_norm(xx):
            r = op.forward(xx) - y
            return 0.5 * np.dot(r.ravel(), r.ravel())

        analytic = op.adjoint(op.forward(x) - y)
        eps = 1e-7
        numeric = np.zeros_like(x)
        it = np.nditer(x, flags=["multi_index"])
        while not it.finished:
            i, j = it.multi_index
            xp, xm = x.copy(), x.copy()
            xp[i, j] += eps
            xm[i, j] -= eps
            numeric[i, j] = (residual_half_norm(xp)
                             - residual_half_norm(xm)) / (2 * eps)
            it.iternext()
        self.assertLess(np.max(np.abs(analytic - numeric)), 1e-6)


class TestFixedSolvableSample(unittest.TestCase):
    def setUp(self):
        self.op, self.y, self.gen, self.x_star = solvable_problem(seed=0)

    def test_residual_improves(self):
        result = solve_inverse(
            self.op, self.y, self.gen,
            pixel_step=1.9, max_iters=80, tol=1e-6,
            lam=0.03, inner_max_iters=80, inner_tol=1e-11)
        self.assertLess(result.final_residual_norm,
                        result.initial_residual_norm)
        self.assertLess(result.final_residual_norm,
                        0.01 * result.initial_residual_norm)
        self.assertEqual(result.iterations, len(result.records))

    def test_reaches_tolerance_stop_state(self):
        result = solve_inverse(
            self.op, self.y, self.gen,
            pixel_step=1.9, max_iters=200, tol=1e-5,
            lam=0.03, inner_max_iters=60, inner_tol=1e-11)
        self.assertEqual(result.status, Status.CONVERGED)
        y_norm = np.linalg.norm(self.y.ravel())
        self.assertLessEqual(
            result.final_residual_norm, 1e-5 * max(1.0, y_norm))

    def test_iteration_budget_status(self):
        result = solve_inverse(
            self.op, self.y, self.gen,
            pixel_step=1.0, max_iters=3, tol=1e-13,
            lam=0.0, inner_max_iters=10, inner_tol=1e-13)
        self.assertEqual(result.status, Status.MAX_ITERS)
        self.assertEqual(result.iterations, 3)
        self.assertEqual(len(result.records), 3)

    def test_records_contain_required_fields(self):
        result = solve_inverse(
            self.op, self.y, self.gen,
            pixel_step=1.0, max_iters=4, tol=1e-13,
            lam=0.01, inner_max_iters=12, inner_tol=1e-9)
        for rec in result.records:
            self.assertTrue(np.isfinite(rec.residual_norm))
            self.assertTrue(np.isfinite(rec.gradient_residual_norm))
            self.assertTrue(np.isfinite(rec.projection_objective))
            self.assertTrue(np.isfinite(rec.offset_l1))
            self.assertGreaterEqual(rec.inner_iters, 1)
            self.assertLessEqual(rec.inner_iters, 12)

    def test_gradient_step_reduces_residual_within_iteration(self):
        # With a stable step, the raw gradient step must not increase the
        # data residual beyond the projected iterate's starting residual.
        result = solve_inverse(
            self.op, self.y, self.gen,
            pixel_step=1.5, max_iters=5, tol=0.0,
            lam=0.03, inner_max_iters=30, inner_tol=0.0)
        first = result.records[0]
        self.assertLessEqual(
            first.gradient_residual_norm, result.initial_residual_norm + 1e-9)


class TestOffsetPenalty(unittest.TestCase):
    def test_l1_penalty_reduces_offset_norm_end_to_end(self):
        op, y, gen, _ = solvable_problem(seed=2)
        kwargs = dict(pixel_step=1.0, max_iters=10, tol=0.0,
                      inner_max_iters=60, inner_tol=0.0)
        free = solve_inverse(op, y, gen, lam=0.0, **kwargs)
        sparse = solve_inverse(op, y, gen, lam=0.5, **kwargs)
        self.assertGreater(free.records[-1].offset_l1,
                           sparse.records[-1].offset_l1)
        self.assertEqual(sparse.records[-1].offset_l1, 0.0)


class TestStopStates(unittest.TestCase):
    def test_all_missing_is_unobservable(self):
        op, _, gen, _ = solvable_problem(seed=4)
        empty_op = MaskedBlur(op.shape, op.kernel, np.zeros(op.shape))
        result = solve_inverse(empty_op, np.zeros(op.shape), gen)
        self.assertEqual(result.status, Status.UNOBSERVABLE)
        self.assertEqual(result.iterations, 0)
        self.assertIn("unconstrain", result.message)

    def test_inner_not_converged_keeps_finite_result(self):
        op, y, gen, _ = solvable_problem(seed=6)
        result = solve_inverse(
            op, y, gen,
            pixel_step=0.5, max_iters=400, tol=0.0,
            lam=0.0, inner_max_iters=1, inner_tol=0.0,
            stall_tol=5e-3, stall_patience=3)
        self.assertEqual(result.status, Status.INNER_NOT_CONVERGED)
        self.assertTrue(np.all(np.isfinite(result.x)))
        self.assertFalse(result.records[-1].inner_converged)
        self.assertGreater(result.final_residual_norm, 0.0)


class TestInputValidation(unittest.TestCase):
    def setUp(self):
        self.op, self.y, self.gen, _ = solvable_problem(seed=8)

    def test_nonfinite_observation_rejected(self):
        y_bad = self.y.copy()
        y_bad[0, 0] = np.nan
        with self.assertRaises(SolveError):
            solve_inverse(self.op, y_bad, self.gen)

    def test_nonfinite_x0_rejected(self):
        with self.assertRaises(SolveError):
            solve_inverse(self.op, self.y, self.gen,
                          x0=np.full(self.op.shape, np.inf))

    def test_observation_shape_conflict_rejected(self):
        with self.assertRaises(SolveError):
            solve_inverse(self.op, self.y[:, :-1], self.gen)

    def test_generator_shape_conflict_rejected(self):
        other_shape = (self.op.shape[0] - 1, self.op.shape[1])
        n = other_shape[0] * other_shape[1]
        rng = np.random.default_rng(0)
        bad_gen = Generator(
            rng.standard_normal((3, 10)), np.zeros(10),
            rng.standard_normal((10, n)), np.zeros(n), other_shape)
        with self.assertRaises(SolveError):
            solve_inverse(self.op, self.y, bad_gen)

    def test_illegal_step_sizes_rejected(self):
        for step in (0.0, -0.5, float("nan")):
            with self.assertRaises(SolveError):
                solve_inverse(self.op, self.y, self.gen, pixel_step=step,
                              max_iters=2)
        upper = 2.0 / self.op.spectral_norm() ** 2
        with self.assertRaises(SolveError):
            solve_inverse(self.op, self.y, self.gen,
                          pixel_step=upper, max_iters=2)

    def test_negative_budget_rejected(self):
        with self.assertRaises(SolveError):
            solve_inverse(self.op, self.y, self.gen, max_iters=-1)

    def test_negative_lam_rejected(self):
        with self.assertRaises(SolveError):
            solve_inverse(self.op, self.y, self.gen, lam=-1e-3)


class TestDeterminism(unittest.TestCase):
    def test_fixed_seed_runs_are_identical(self):
        kwargs = dict(shape=(10, 10), missing_fraction=0.25,
                      max_iters=5, pixel_step=1.0,
                      lam=0.02, inner_max_iters=20,
                      data_seed=7, mask_seed=11, weight_seed=2024)
        first = solve(**kwargs)
        second = solve(**kwargs)
        np.testing.assert_array_equal(first.x, second.x)
        self.assertEqual(first.final_residual_norm,
                         second.final_residual_norm)


if __name__ == "__main__":
    unittest.main()
